import {MAX_BYTES,parseTranscript,selectCues} from './model.mjs';
export function mount({container,search='',signal,theme}={}){
 const root=container.attachShadow({mode:'open'});let data=null,disposed=false,generation=0,page=0;
 root.innerHTML='<section><p>ATHENA · EVIDENCE FIRST</p><h2>Video study desk</h2><p>Study the problem, failed attempts, solution and verification. Imported captions are evidence, not proof of mastery.</p><label>Open normalized transcript JSON<input id="import" type="file" accept=".json,application/json"></label><button id="clear">Clear transcript</button><p id="notice" role="status">Generate JSON with scripts/video_learning.py from captions you are authorized to use. Nothing is uploaded or saved in browser storage. Leaving clears this session.</p><p id="identity"></p><p id="count" aria-live="polite"></p><div id="cues"></div><button id="previous">Previous 50</button><button id="next">Next 50</button><footer>Coverage: imported cues only. Full video, visual evidence and channel coverage are not established. Automatic captions may be inaccurate or repeat. Use timestamp links to verify against the original. Curriculum admission remains separate and review-gated.</footer></section>';
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./style.css',import.meta.url);root.prepend(css);
 const $=s=>root.querySelector(s),node=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
 function render(){if(disposed)return;$('#cues').replaceChildren();$('#identity').textContent=data?`${data.video_id} · ${data.language} · ${data.origin} · ${data.automatic?'Automatic captions':'Caption origin supplied by importer'} · SHA256 ${data.sha256}`:'';const result=data?selectCues(data,search,page):{total:0,pages:1,page:0,cues:[]};page=result.page;$('#count').textContent=`${result.total} matching cues · page ${page+1}/${result.pages}`;$('#previous').disabled=page===0;$('#next').disabled=page+1>=result.pages;
 for(const c of result.cues){const card=node('article',''),link=node('a',`${c.id} · ${(c.start_ms/1000).toFixed(1)}–${(c.end_ms/1000).toFixed(1)} seconds ↗`);link.href=c.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link,node('p',c.text));$('#cues').append(card);}}
 $('#import').onchange=async e=>{const file=e.target.files?.[0],token=++generation;e.target.value='';if(!file||disposed)return;$('#notice').textContent='Reading selected transcript…';try{if(file.size>MAX_BYTES)throw Error('Transcript exceeds 16 MiB.');const bytes=await file.arrayBuffer();if(disposed||token!==generation)return;const next=parseTranscript(new Uint8Array(bytes));if(disposed||token!==generation)return;data=next;page=0;render();$('#notice').textContent='Imported for this session only. Source claims and completeness still require review.';}catch(error){if(!disposed&&token===generation)$('#notice').textContent='Import refused; previous transcript retained. '+error.message;}};
 $('#clear').onclick=()=>{generation++;data=null;page=0;render();$('#notice').textContent='Transcript cleared.';};$('#previous').onclick=()=>{page--;render();};$('#next').onclick=()=>{page++;render();};
 function unmount(){if(disposed)return;disposed=true;generation++;data=null;root.replaceChildren();signal?.removeEventListener('abort',unmount);}function setTheme(t){container.dataset.theme=t==='light'?'light':'dark';}setTheme(theme);render();signal?.addEventListener('abort',unmount,{once:true});if(signal?.aborted)unmount();return {unmount,setTheme,setSearch(q){search=String(q);page=0;render();}};
}
